/* @lc app=leetcode id=904 lang=kotlin */ class Solution { fun totalFruit(fruits: IntArray): Int = HashMap<Int, Int>().let { m -> fruits.indices.fold(0 to 0) { (l, best), r -> m.merge(fruits[r], 1) { a, b -> a + b }.let { generateSequence(l) { it + 1 }.first { k -> m.size <= 2 || m.merge(fruits[k], -1) { a, b -> a + b }.let { c -> if (c == 0) m.remove(fruits[k]) }.let { false } } }.let { nl -> nl to maxOf(best, r - nl + 1) } }.second } }